{
  "command": "ls -la /app/data/input_files/",
  "description": "List input files"
}

{
  "command": "which pdftotext python3 unzip libreoffice 2>/dev/null; echo \"---\"; python3 -c \"import openpyxl\" 2>&1 | head -1",
  "description": "Check available extraction tools"
}

{
  "command": "cd /app/data/input_files && pdftotext -layout "01_入院病史与查体.pdf" /tmp/01.txt && pdftotext -layout "03_床旁交班摘要.pdf" /tmp/03.txt && pdftotext -layout "04_病历资料与检查安全规则.pdf" /tmp/04.txt && echo "=== xlsx ===" && python3 -c "
import openpyxl
wb=openpyxl.load_workbook('02_外院检验转录与门诊交接.xlsx', data_only=True)
for ws in wb.worksheets:
    print('### SHEET:', ws.title)
    for row in ws.iter_rows(values_only=True):
        print(row)
"",
  "description": "Extract text from all input files"
}

{
  "command": "echo \"=========== 01 入院病史与查体 ===========\"; cat /tmp/01.txt; echo; echo \"=========== 03 床旁交班摘要 ===========\"; cat /tmp/03.txt; echo; echo \"=========== 04 病历资料与检查安全规则 ===========\"; cat /tmp/04.txt",
  "description": "Print extracted PDF texts"
}

{
  "command": "python3 -c \"import docx; print(docx.__version__)\" 2>&1; mkdir -p /app/output && echo \"output dir ready\"",
  "description": "Check python-docx availability and make output dir"
}

{
  "command": "ls -la /app/output/",
  "description": "Verify output deliverables"
}

{
  "command": "python3 -c "
from docx import Document
d=Document('/app/output/内分泌专科入院评估.docx')
print('paragraphs:', len(d.paragraphs))
for p in d.paragraphs:
    if p.style.name.startswith('Heading'):
        print(p.style.name, '|', p.text)
"",
  "description": "Verify docx structure/headings"
}
